/* Usage: lmx_documents_pdf_example [report.pdf] */
#include "pdfgen.h"
int main(int argc,char **argv) {
    struct pdf_info info={.creator="LMX C99",.title="Example report"};
    struct pdf_doc *pdf=pdf_create(PDF_A4_WIDTH,PDF_A4_HEIGHT,&info);
    const char *path=argc>1?argv[1]:"report.pdf";int status=1;
    if(!pdf)return 1;
    if(pdf_set_font(pdf,"Helvetica")!=0 || !pdf_append_page(pdf))goto done;
    if(pdf_add_text(pdf,NULL,"A report generated by a C99 application",16,50,780,PDF_BLACK)<0)goto done;
    status=pdf_save(pdf,path)!=0;
 done:
    pdf_destroy(pdf);return status;
}
